/* Default Funnel Environment graph, generated by the deterministic Foundry core. */
(function(root){
'use strict';
if(!root.FunnelFoundry)throw Error('FunnelFoundry core must load before environment data.');
let config=root.FunnelFoundry.DEFAULT_CONFIG;
try{
  const saved=JSON.parse(root.localStorage&&root.localStorage.getItem('moor.funnel-foundry.config.v1')||'null');
  if(saved)config=saved;
}catch(e){}
root.FUNNEL_ENVIRONMENT_GRAPH=root.FunnelFoundry.build(config);
})(window);
